draw:
var F = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = F;
var a = p.angle * Math.PI / 180;
var m = p.m, M = p.M, g = 9.8;
var A = m * g * Math.sin(a) * Math.cos(a) / (M + m * Math.sin(a) * Math.sin(a));
var sdd = (M + m) * g * Math.sin(a) / (M + m * Math.sin(a) * Math.sin(a));

var floorY = H * 0.86;
var x0 = W * 0.16;
var base = W * 0.56;
var hgt = base * Math.tan(a);
if (hgt > H * 0.56) { base = (H * 0.56) / Math.tan(a); hgt = H * 0.56; }
var apexX = x0, apexY = floorY - hgt;
var rightX = x0 + base;

// floor
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(0, floorY); ctx.lineTo(W, floorY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("frictionless floor", W * 0.02, floorY + 16);

// wedge
ctx.fillStyle = C.paper;
ctx.strokeStyle = C.ink;
ctx.beginPath();
ctx.moveTo(apexX, apexY); ctx.lineTo(rightX, floorY); ctx.lineTo(apexX, floorY);
ctx.closePath(); ctx.fill(); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("M", apexX + 16, floorY - 14);

// angle mark at the bottom right corner
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(rightX, floorY, 26, Math.PI, Math.PI + a); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("alpha = " + p.angle.toFixed(0) + " deg", rightX - 78, floorY - 8);

// block a third of the way down the face
var f = 0.38;
var bx = apexX + (rightX - apexX) * f;
var by = apexY + (floorY - apexY) * f;
var bs = 18;
var nx = -Math.sin(a), ny = -Math.cos(a);
ctx.save();
ctx.translate(bx + nx * bs * 0.7, by + ny * bs * 0.7);
ctx.rotate(a);
ctx.fillStyle = C.paper;
ctx.fillRect(-bs / 2, -bs / 2, bs, bs);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.8;
ctx.strokeRect(-bs / 2, -bs / 2, bs, bs);
ctx.restore();
var cxb = bx + nx * bs * 0.7, cyb = by + ny * bs * 0.7;
ctx.fillStyle = C.ink;
ctx.fillText("m", cxb - 20, cyb - 10);

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 7 * Math.cos(ang - 0.4), y2 - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 7 * Math.cos(ang + 0.4), y2 - 7 * Math.sin(ang + 0.4));
  ctx.closePath(); ctx.fill();
}

// normal force on block (does no work in the ground frame only if wedge is fixed)
arrow(cxb, cyb, cxb + nx * 44, cyb + ny * 44, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("N (never appears in L)", cxb + nx * 44 - 30, cyb + ny * 44 - 8);

// gravity on block
arrow(cxb, cyb, cxb, cyb + 40, C.ink);
ctx.fillStyle = C.ink;
ctx.fillText("mg", cxb + 6, cyb + 38);

// s along the face
var sx = apexX + (rightX - apexX) * 0.70, sy = apexY + (floorY - apexY) * 0.70;
arrow(apexX, apexY, sx, sy, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("s: block along the face", apexX + 26, apexY + 34);

// X of the wedge
arrow(rightX - 40, floorY + 26, rightX + 20, floorY + 26, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("X: wedge along the floor", rightX - 150, floorY + 42);

out.note = "wedge acceleration " + A.toFixed(2) + " m/s^2, block along the face " +
  sdd.toFixed(2) + " m/s^2";
